package main

import (
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/dashboard"
	"github.com/spf13/cobra"
)

type intRunFlags struct {
	addr      string
	port      int
	noBrowser bool
}

var intRunOpts intRunFlags

var intRunCmd = &cobra.Command{
	Use:   "run [dir]",
	Short: "Launch the local integration dashboard",
	Long: "Start a local web dashboard that visualizes the integrations scaffolded under dir " +
		"(default: the current directory) — their template, pinned source, version, and scaffold values. " +
		"The dashboard is served from the CLI itself and opens in your browser; it does not start any " +
		"integration processes. Press Ctrl+C to stop.",
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("run: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("run: %s is not a directory", root)
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		return dashboard.Serve(ctx, dashboard.Options{
			Root:        root,
			Addr:        intRunOpts.addr,
			Port:        intRunOpts.port,
			OpenBrowser: !intRunOpts.noBrowser,
			Version:     version,
			Stdout:      cmd.OutOrStdout(),
			Stderr:      cmd.ErrOrStderr(),
		})
	},
}

func init() {
	f := intRunCmd.Flags()
	f.StringVar(&intRunOpts.addr, "addr", "127.0.0.1", "host/interface to bind")
	f.IntVarP(&intRunOpts.port, "port", "p", 8730, "port to bind (0 picks a free port)")
	f.BoolVar(&intRunOpts.noBrowser, "no-browser", false, "do not open the dashboard in a browser")
	intCmd.AddCommand(intRunCmd)
}

