// Package topology reads the generated system topology record
// (.intropy/topology.json) that an integration system's AppHost project
// emits. The record declares the system's shape: its components (blocks) and
// the wiring between them, expressed inline on each component — the topics it
// subscribes to and publishes on, the API contracts it provides and consumes,
// and the external connectors it uses. Top-level topics[] and connectors[]
// sections carry the shared metadata (contracts, transports, external systems)
// those inline references point at.
//
// The CLI only consumes this file; it never writes one. Consumers fall back to
// their own heuristics when a system has no topology record.
package topology

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

const (
	// APIVersion is the topology.json schema this CLI understands. A record
	// with any other apiVersion is an error, not a guess.
	APIVersion = "topology.intropy.io/v1"

	// Kind is the expected document kind under APIVersion.
	Kind = "SystemTopology"

	// RelPath is where the topology record lives inside a system root,
	// sibling to the per-project scaffold record convention.
	RelPath = ".intropy/topology.json"
)

// Topology is one system's declared graph. Wiring is inlined on each component
// rather than kept in a separate edge list: a component names the topics it
// subscribes to and publishes on and the connectors it uses. The top-level
// Topics and Connectors sections are lookup tables the inline references
// resolve against (contract, transport, external system).
type Topology struct {
	APIVersion string      `json:"apiVersion"`
	Kind       string      `json:"kind,omitempty"`
	System     string      `json:"system"`
	Components []Component `json:"components,omitempty"`
	Topics     []Topic     `json:"topics,omitempty"`
	Connectors []Connector `json:"connectors,omitempty"`
	// APIs, and each component's Provides/Consumes below, are the contract
	// (request/response) surfaces. Their element shape is not yet finalized,
	// so they are parsed opaquely: preserved for round-tripping to the
	// frontend without asserting a schema the CLI does not yet render.
