// which joins it to its .intropy/scaffold.json project, is its Name relative
// to the system root.
type Component struct {
	Name       string         `json:"name"`
	Kind       string         `json:"kind"`
	Subscribes []TopicRef     `json:"subscribes,omitempty"`
	Publishes  []Publication  `json:"publishes,omitempty"`
	Connectors []ConnectorUse `json:"connectors,omitempty"`
	// Provides/Consumes are contract surfaces, parsed opaquely (see APIs).
	Provides []json.RawMessage `json:"provides,omitempty"`
	Consumes []json.RawMessage `json:"consumes,omitempty"`
}

// TopicRef is a component's subscription to a pub/sub topic.
type TopicRef struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// Publication is a component's output onto a pub/sub topic. Port names the
// component output the message leaves through.
type Publication struct {
	Port   string `json:"port,omitempty"`
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// ConnectorUse is a component's use of an external connector. Direction is
// "in" (external → component) or "out" (component → external).
type ConnectorUse struct {
	Connector string `json:"connector"`
	Direction string `json:"direction"`
}

// Topic is a declared pub/sub topic: the metadata for a (PubSub, Topic) pair
// components reference. Contract is the message contract it carries;
// Publishers/Subscribers name the components on each end.
type Topic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Transport describes how a connector moves data. SupportsInput/SupportsOutput
// declare the directions the transport itself can carry.
type Transport struct {
	Type           string `json:"type"`
	SupportsInput  bool   `json:"supportsInput"`
	SupportsOutput bool   `json:"supportsOutput"`
}

// Connector is an external system integration point. ExternalSystem is the
// system it fronts, Directions the directions it is wired in, and UsedBy the
// components that use it.
type Connector struct {
	Name           string    `json:"name"`
	ExternalSystem string    `json:"externalSystem,omitempty"`
	Transport      Transport `json:"transport"`
	Directions     []string  `json:"directions,omitempty"`
	UsedBy         []string  `json:"usedBy,omitempty"`
}

// Load reads and parses a topology.json file. A record whose apiVersion this
// CLI does not understand is an error, not a guess.
func Load(path string) (*Topology, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read topology record %s: %w", path, err)
	}
	var t Topology
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse topology record %s: %w", path, err)
	}
	if t.APIVersion != APIVersion {
		return nil, fmt.Errorf("topology record %s: unsupported apiVersion %q (this CLI understands %q)",
			path, t.APIVersion, APIVersion)
	}
	return &t, nil
}

// listSkipDirs mirrors the scaffold walk: directory names never worth
// descending into when scanning for system roots.
var listSkipDirs = map[string]bool{
	".git":         true,
	".intropy":     true,
	"node_modules": true,
	"bin":          true,
	"dist":         true,
}

// Entry is one system found by List: the directory holding the record plus
// the record itself, flattened into one self-describing JSON document.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// List walks the tree rooted at root and returns an entry for every
// directory that contains .intropy/topology.json, in lexical walk order.
// A matched directory is not descended into — systems do not nest.
// Unreadable directories and malformed records become warnings rather than
// failures so one bad record cannot hide the rest.
func List(root string) (entries []Entry, warnings []error) {
	walkErr := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			warnings = append(warnings, err)
			return nil
		}
		if !d.IsDir() {
			return nil
		}
		if path != root && listSkipDirs[d.Name()] {
			return fs.SkipDir
		}

		record := filepath.Join(path, filepath.FromSlash(RelPath))
		if _, err := os.Stat(record); err != nil {
			if !os.IsNotExist(err) {
				warnings = append(warnings, fmt.Errorf("stat %s: %w", record, err))
			}
			return nil
		}
		t, err := Load(record)
		if err != nil {
			// Still a system root — don't descend looking for more.
			warnings = append(warnings, err)
			return fs.SkipDir
		}
		entries = append(entries, Entry{Path: path, Topology: *t})
		return fs.SkipDir
	})
	if walkErr != nil {
		warnings = append(warnings, walkErr)
	}
	return entries, warnings
}

