    {"pubsub": "price-pubsub", "topic": "price-b2c", "contract": "Price.Contracts.B2CPrice",
     "publishers": ["extractor"], "subscribers": ["wms-loader"]}
  ],
  "connectors": [
    {"name": "erp", "externalSystem": "erp",
     "transport": {"type": "http", "supportsInput": false, "supportsOutput": true},
     "directions": ["out"], "usedBy": ["erp-loader"]},
    {"name": "price-master", "externalSystem": "price-master",
     "transport": {"type": "sftp", "supportsInput": true, "supportsOutput": true},
     "directions": ["in"], "usedBy": ["extractor"]}
  ]
}`

func writeRecord(t *testing.T, systemDir, body string) string {
	t.Helper()
	dir := filepath.Join(systemDir, ".intropy")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "topology.json")
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

func TestLoadValid(t *testing.T) {
	path := writeRecord(t, t.TempDir(), validRecord)
	got, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if got.System != "distribution" {
		t.Errorf("system = %q, want %q", got.System, "distribution")
	}
	if got.Kind != Kind {
		t.Errorf("kind = %q, want %q", got.Kind, Kind)
	}
	if len(got.Components) != 2 || len(got.Topics) != 2 || len(got.Connectors) != 2 {
		t.Fatalf("entity counts = %d/%d/%d, want 2/2/2",
			len(got.Components), len(got.Topics), len(got.Connectors))
	}
	if c := got.Components[0]; c.Kind != "extractor" || len(c.Publishes) != 2 {
		t.Fatalf("extractor = %+v", c)
	}
	if p := got.Components[0].Publishes[0]; p.Port != "b2c" || p.PubSub != "price-pubsub" || p.Topic != "price-b2c" {
		t.Errorf("publish = %+v", p)
	}
	if u := got.Components[0].Connectors[0]; u.Connector != "price-master" || u.Direction != "in" {
		t.Errorf("connector use = %+v", u)
	}
	if s := got.Components[1].Subscribes[0]; s.PubSub != "price-pubsub" || s.Topic != "price-b2b" {
		t.Errorf("subscribe = %+v", s)
	}
	if tp := got.Topics[0]; tp.Topic != "price-b2b" || tp.Contract != "Price.Contracts.B2BPrice" {
		t.Errorf("topic = %+v", tp)
	}
	if cn := got.Connectors[1]; cn.Name != "price-master" || cn.Transport.Type != "sftp" ||
		!cn.Transport.SupportsInput || !cn.Transport.SupportsOutput {
		t.Errorf("connector = %+v", cn)
	}
}

func TestLoadMissing(t *testing.T) {
	_, err := Load(filepath.Join(t.TempDir(), "nope.json"))
	if err == nil {
		t.Fatal("expected error for missing file")
	}
}

func TestLoadMalformed(t *testing.T) {
	path := writeRecord(t, t.TempDir(), "{not json")
	if _, err := Load(path); err == nil || !strings.Contains(err.Error(), "parse topology record") {
		t.Fatalf("err = %v, want parse error", err)
	}
}

// An unknown apiVersion is surfaced as an error, not guessed at. An
// old-schema record (integer schemaVersion, no apiVersion) trips the same
// check, so it degrades to a List warning rather than mis-parsing.
func TestLoadUnsupportedAPIVersion(t *testing.T) {
	path := writeRecord(t, t.TempDir(), `{"apiVersion": "topology.intropy.io/v99", "system": "x"}`)
	if _, err := Load(path); err == nil || !strings.Contains(err.Error(), "unsupported apiVersion") {
		t.Fatalf("err = %v, want unsupported apiVersion error", err)
	}
}

// An old-schema record (integer schemaVersion, system as an object) is
// rejected rather than mis-parsed, so it degrades to a List warning. It fails
// at unmarshal (system is not a string) before the apiVersion check, which is
// still a rejection — the guarantee is that Load never silently accepts it.
func TestLoadOldSchemaIsRejected(t *testing.T) {
	path := writeRecord(t, t.TempDir(), `{"schemaVersion": 1, "system": {"name": "x"}}`)
	if _, err := Load(path); err == nil {
		t.Fatal("expected error for old-schema record, got nil")
	}
}

func TestListFindsSystems(t *testing.T) {
	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "distribution", "price-distribution"), validRecord)
	other := strings.Replace(validRecord, `"system": "distribution"`, `"system": "order-intake"`, 1)
	writeRecord(t, filepath.Join(root, "sales", "order-intake"), other)
	// A dir without a record is walked through, not reported.
	if err := os.MkdirAll(filepath.Join(root, "empty"), 0o755); err != nil {
		t.Fatal(err)
	}

	entries, warnings := List(root)
	if len(warnings) != 0 {
		t.Fatalf("warnings = %v", warnings)
	}
	if len(entries) != 2 {
		t.Fatalf("entries = %d, want 2", len(entries))
	}
	// Lexical walk order: distribution before sales.
	if entries[0].System != "distribution" || entries[1].System != "order-intake" {
		t.Errorf("systems = %q, %q", entries[0].System, entries[1].System)
	}
	if want := filepath.Join(root, "distribution", "price-distribution"); entries[0].Path != want {
		t.Errorf("path = %q, want %q", entries[0].Path, want)
	}
}

// A malformed record is a warning, and its directory is still treated as a
// system root (not descended into), so one bad system cannot hide the rest.
func TestListMalformedIsWarning(t *testing.T) {
	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "bad"), "{broken")
	writeRecord(t, filepath.Join(root, "good"), validRecord)

	entries, warnings := List(root)
	if len(entries) != 1 || entries[0].System != "distribution" {
		t.Fatalf("entries = %+v, want just the good system", entries)
	}
	if len(warnings) != 1 {
		t.Fatalf("warnings = %v, want 1", warnings)
	}
}

func TestListSkipsUninterestingDirs(t *testing.T) {
	root := t.TempDir()
	writeRecord(t, filepath.Join(root, "node_modules", "pkg"), validRecord)
	writeRecord(t, filepath.Join(root, ".git", "sys"), validRecord)

	entries, warnings := List(root)
	if len(entries) != 0 || len(warnings) != 0 {
		t.Fatalf("entries = %v, warnings = %v, want none", entries, warnings)
	}
}

