import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeScaffold(t *testing.T, dir, tmpl, version string) {
	t.Helper()
	intropyDir := filepath.Join(dir, ".intropy")
	if err := os.MkdirAll(intropyDir, 0o755); err != nil {
		t.Fatal(err)
	}
	body := `{"schemaVersion":1,"template":"` + tmpl + `","owner":"integrio-intropy","repo":"intropy-templates","version":"` + version + `","dataFlow":"both","values":{"appId":"int1"}}` + "\n"
	if err := os.WriteFile(filepath.Join(intropyDir, "scaffold.json"), []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func testHandler(t *testing.T, root string) http.Handler {
	t.Helper()
	h, err := newHandler(root, "test")
	if err != nil {
		t.Fatalf("newHandler: %v", err)
	}
	return h
}

