// TestTopologyPopulated checks that a system's declared topology record is
// served with its path normalized to the same root-relative identifier the
// integration endpoints use.
func TestTopologyPopulated(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	system := filepath.Join(tmp, "distribution", "product-distribution")
	writeScaffold(t, filepath.Join(system, "pim-extractor"), "extractor", "v0.1.6")
	if err := os.MkdirAll(filepath.Join(system, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	record := `{
  "apiVersion": "topology.intropy.io/v1",
  "kind": "SystemTopology",
  "system": "product-distribution",
  "components": [{"name": "pim-extractor", "kind": "extractor",
    "publishes": [{"port": "default", "pubsub": "pubsub", "topic": "product-raw"}]}],
  "topics": [{"pubsub": "pubsub", "topic": "product-raw", "contract": "Integrio.Contracts.RawProduct"}]
}`
